import{c as o,d as e,E as n,k as s,u as d,I as v,V as l,e as i,F as g,r as f,A as B,W as p,w as q,C as x,G as j,b,n as R,t as c}from"./index-Bt_uf6Lk.js";const T=(r,m)=>{const a=r.__vccOpts||r;for(const[u,t]of m)a[u]=t;return a},y={class:"page narrow rules"},z={class:"stack"},E={class:"panel"},C={class:"panel"},G={class:"actions",style:{"margin-top":"16px"}},S={class:"hd"},L={class:"ic"},P={class:"nm"},k={class:"tg"},A={class:"ds"},N={class:"panel"},h={class:"wtable"},w={style:{color:"var(--cyan)"}},I={style:{color:"var(--amber)"}},D={style:{color:"var(--lime)"}},O={__name:"Rules",setup(r){return(m,a)=>{const u=j("router-link");return b(),o("div",y,[e("div",z,[a[19]||(a[19]=n('<div class="panel" data-v-ad8a672e><h1 class="hero-title" data-v-ad8a672e>RÈGLES DU JEU</h1><p class="sub" style="margin-bottom:0;" data-v-ad8a672e> Stratégie au tour par tour pour <b data-v-ad8a672e>4 à 8 joueurs</b>. Chaque joueur dirige un <b data-v-ad8a672e>dôme</b> alimenté par des <b class="lime" data-v-ad8a672e>Batteries</b>. Chaque jour, tout le monde donne ses ordres en secret, puis le tour est résolu pour tous en même temps. </p></div><div class="panel" data-v-ad8a672e><div class="ptitle" data-v-ad8a672e>01 · But du jeu</div><ul data-v-ad8a672e><li data-v-ad8a672e>La partie dure <b data-v-ad8a672e>15 jours</b> (15 tours).</li><li data-v-ad8a672e>À la fin, le joueur qui possède le plus de <b class="teal" data-v-ad8a672e>Razoonium</b> gagne.</li><li data-v-ad8a672e>Les dômes encore allumés passent <b data-v-ad8a672e>toujours devant</b> les dômes éteints, quel que soit leur Razoonium.</li><li data-v-ad8a672e>Si un seul dôme reste allumé avant la fin, la partie s&#39;arrête et ce joueur gagne.</li></ul><h3 data-v-ad8a672e>Classement</h3><ol data-v-ad8a672e><li data-v-ad8a672e>Dômes encore allumés d&#39;abord.</li><li data-v-ad8a672e>Puis le plus de <b class="teal" data-v-ad8a672e>Razoonium</b>.</li><li data-v-ad8a672e>Égalité : le plus de Batteries, puis le plus de Bouclier.</li><li data-v-ad8a672e>Entre dômes éteints : celui qui a tenu le plus longtemps passe devant.</li></ol></div>',2)),e("div",E,[a[2]||(a[2]=e("div",{class:"ptitle"},"02 · Ressources",-1)),e("h3",null,[s(l,{class:"mi",size:"1.1em",icon:d(v).battery},null,8,["icon"]),a[0]||(a[0]=i(" Batteries",-1))]),a[3]||(a[3]=n('<ul data-v-ad8a672e><li data-v-ad8a672e>Stock initial : <b class="lime" data-v-ad8a672e>10 Batteries</b>.</li><li data-v-ad8a672e>C&#39;est la ressource que tu dépenses pour agir. Elle peut être <b class="red" data-v-ad8a672e>volée</b>.</li><li data-v-ad8a672e>Coût de vie : ton dôme consomme <b data-v-ad8a672e>1 Batterie</b> à chaque tour.</li><li data-v-ad8a672e>Si tu finis un tour à <b class="red" data-v-ad8a672e>0 Batterie ou moins</b>, ton dôme s&#39;éteint : tu ne joues plus, mais ton Razoonium reste compté (derrière les dômes allumés).</li></ul><div class="ex warn" data-v-ad8a672e> Si tu engages toutes tes Batteries, le coût de vie te fait passer à −1. Seuls tes gains du tour (Génération, attaque restituée, pillage) peuvent alors te sauver. Garde une marge, surtout en cas de Tempête (−1 de plus). </div>',2)),e("h3",null,[s(l,{class:"mi",size:"1.1em",icon:d(v).razoonium},null,8,["icon"]),a[1]||(a[1]=i(" Razoonium",-1))]),a[4]||(a[4]=n('<ul data-v-ad8a672e><li data-v-ad8a672e>C&#39;est <b data-v-ad8a672e>ton score</b>.</li><li data-v-ad8a672e>On l&#39;obtient en <b data-v-ad8a672e>raffinant</b> des Batteries (1 Batterie → 1 Razoonium) ou en <b data-v-ad8a672e>remportant un lot d&#39;Enchère</b>.</li><li data-v-ad8a672e>Il est <b data-v-ad8a672e>définitif</b> : il ne se dépense pas, ne se perd pas et <b data-v-ad8a672e>ne peut pas être volé</b>.</li><li data-v-ad8a672e>Une Batterie raffinée ne sert plus à agir, survivre ou se défendre. Tout l&#39;enjeu est de choisir <b data-v-ad8a672e>quand</b> transformer ta puissance en score.</li></ul><div class="ex warn" data-v-ad8a672e> Le raffinage se fait <b data-v-ad8a672e>en fin de tour, après les attaques</b> : les Batteries misées en Raffinage <b class="red" data-v-ad8a672e>peuvent être pillées</b> (en dernier, après ta réserve et ta Génération). Seul ce qui reste de la mise devient du Razoonium. </div><h3 data-v-ad8a672e>Réserve libre</h3><ul data-v-ad8a672e><li data-v-ad8a672e>Les Batteries que tu n&#39;engages dans aucune action forment ta <b data-v-ad8a672e>réserve libre</b>.</li><li data-v-ad8a672e>Elle paie le coût de vie et c&#39;est <b class="red" data-v-ad8a672e>la première cible du pillage</b>.</li></ul>',4))]),e("div",C,[a[5]||(a[5]=n('<div class="ptitle" data-v-ad8a672e>03 · Tour de jeu</div><ul data-v-ad8a672e><li data-v-ad8a672e>Chaque tour dure un temps fixé à la création de la partie (<b data-v-ad8a672e>24h, 12h, 6h ou 1h</b>).</li><li data-v-ad8a672e>Avant l&#39;échéance, répartis tes Batteries <b data-v-ad8a672e>en secret</b> entre les 7 actions. Tu peux en combiner plusieurs dans le même tour, sans dépasser ce que tu possèdes.</li><li data-v-ad8a672e>Tes ordres restent modifiables jusqu&#39;à la résolution.</li><li data-v-ad8a672e>Avec la <b data-v-ad8a672e>résolution anticipée</b>, le tour est résolu dès que tous les dômes allumés ont validé.</li><li data-v-ad8a672e>Sans ordre validé, ton dôme ne fait rien : tout reste en réserve.</li></ul>',2)),e("div",G,[(b(!0),o(g,null,f(d(B),t=>(b(),o("div",{key:t.key,class:"acard on",style:R({"--a":t.color})},[e("div",S,[e("div",L,[s(l,{icon:t.icon},null,8,["icon"])]),e("div",null,[e("div",P,c(t.name),1),e("div",k,c(t.tag),1)])]),e("div",A,c(t.desc),1)],4))),128))])]),a[20]||(a[20]=n('<div class="panel" data-v-ad8a672e><div class="ptitle" data-v-ad8a672e>04 · Générer</div><ul data-v-ad8a672e><li data-v-ad8a672e>La mise est consommée et remplacée en fin de tour par <b data-v-ad8a672e>⌊mise × multiplicateur⌋</b> (arrondi à l&#39;inférieur).</li><li data-v-ad8a672e>Multiplicateur : <b class="lime" data-v-ad8a672e>×1,5</b>, <b class="lime" data-v-ad8a672e>×2</b> avec un Pacte scellé.</li><li data-v-ad8a672e>En <b data-v-ad8a672e>Abondance</b> : <b class="lime" data-v-ad8a672e>×2</b>, et <b class="lime" data-v-ad8a672e>×2,5</b> avec un Pacte scellé.</li><li data-v-ad8a672e>La mise en Génération <b class="red" data-v-ad8a672e>peut être pillée</b> : le rendement est calculé sur ce qu&#39;il en reste après les attaques.</li></ul><div class="ex" data-v-ad8a672e><b data-v-ad8a672e>Exemple</b> : tu mets 6 en Génération. Sans attaque, tu récupères ⌊6 × 1,5⌋ = <b data-v-ad8a672e>9</b> (+3). Si on te pille 2 Batteries dans ta Génération, tu ne récupères que ⌊4 × 1,5⌋ = <b data-v-ad8a672e>6</b>. </div></div><div class="panel" data-v-ad8a672e><div class="ptitle" data-v-ad8a672e>05 · Défendre</div><ul data-v-ad8a672e><li data-v-ad8a672e>Chaque Batterie en Défense crée <b data-v-ad8a672e>1 point de Bouclier</b>.</li><li data-v-ad8a672e>Un Bouclier posé le jour J est <b data-v-ad8a672e>actif dès ce tour</b> et protège pendant les tours J, J+1 et J+2, puis il expire.</li><li data-v-ad8a672e>Chaque point de dégât détruit 1 point de Bouclier, <b data-v-ad8a672e>les plus anciens d&#39;abord</b>.</li><li data-v-ad8a672e>Les Boucliers ne sont pas pillables.</li></ul></div><div class="panel" data-v-ad8a672e><div class="ptitle" data-v-ad8a672e>06 · Attaquer &amp; piller</div><p data-v-ad8a672e>Tu ne peux attaquer qu&#39;<b data-v-ad8a672e>un seul joueur par tour</b>. Avec X Batteries d&#39;attaque :</p><ol style="margin-top:8px;" data-v-ad8a672e><li data-v-ad8a672e>Celles qui servent à casser le Bouclier de la cible sont <b class="red" data-v-ad8a672e>perdues</b>.</li><li data-v-ad8a672e>Celles qui le dépassent (<b data-v-ad8a672e>dégâts nets</b>) te sont <b class="lime" data-v-ad8a672e>restituées</b> en fin de tour.</li><li data-v-ad8a672e>Chaque dégât net <b data-v-ad8a672e>vole 1 Batterie</b> à la cible : d&#39;abord dans sa <b data-v-ad8a672e>réserve libre</b> (y compris mises d&#39;enchère remboursées et transferts reçus ce tour), puis dans sa <b data-v-ad8a672e>Génération</b>, puis dans son <b data-v-ad8a672e>Raffinage</b>.</li><li data-v-ad8a672e>On ne vole que ce qui existe : Boucliers, Razoonium déjà acquis, mises d&#39;enchère gagnantes, attaques et transferts envoyés sont hors d&#39;atteinte.</li></ol><p style="margin-top:10px;" data-v-ad8a672e><b data-v-ad8a672e>Plusieurs attaquants</b> sur la même cible : leurs attaques s&#39;additionnent pour casser le Bouclier, puis dégâts nets et butin sont répartis au prorata de la mise de chacun. </p><div class="ex" data-v-ad8a672e><b data-v-ad8a672e>Exemple</b> : tu attaques Nat avec <b data-v-ad8a672e>7</b>. Nat a un Bouclier de 3, une réserve libre de 2 et 5 en Génération. <ul data-v-ad8a672e><li data-v-ad8a672e>3 Batteries cassent son Bouclier et sont perdues.</li><li data-v-ad8a672e>Les 4 restantes te reviennent et volent 4 Batteries : 2 dans sa réserve, puis 2 dans sa Génération.</li><li data-v-ad8a672e>Tu finis le tour à <b class="lime" data-v-ad8a672e>+8</b> (4 restituées + 4 volées) pour 7 engagées.</li><li data-v-ad8a672e>Nat génère sur les 3 restantes : ⌊3 × 1,5⌋ = 4 au lieu de 7.</li></ul></div></div><div class="panel" data-v-ad8a672e><div class="ptitle" data-v-ad8a672e>07 · Pacte</div><ul data-v-ad8a672e><li data-v-ad8a672e>Proposer un Pacte <b data-v-ad8a672e>ne coûte aucune Batterie</b>. Un seul Pacte par tour.</li><li data-v-ad8a672e><b data-v-ad8a672e>Engagement</b> : accepté ou non, tu ne peux <b class="red" data-v-ad8a672e>ni attaquer ni défendre</b> ce tour.</li><li data-v-ad8a672e><b data-v-ad8a672e>Exposition</b> : tes Boucliers sont <b class="red" data-v-ad8a672e>inactifs</b> pendant ce tour. Toute attaque te pille directement, sans rien casser. Tes Boucliers ne sont pas abîmés et redeviennent actifs au tour suivant.</li><li data-v-ad8a672e><b data-v-ad8a672e>Pacte scellé</b> : uniquement si les deux joueurs se proposent mutuellement le Pacte. Les deux alliés ont une Génération <b class="lime" data-v-ad8a672e>×2</b> (×2,5 en Abondance).</li><li data-v-ad8a672e>Pacte non réciproque : pas de bonus, mais l&#39;engagement et l&#39;exposition s&#39;appliquent quand même.</li></ul><div class="ex warn" data-v-ad8a672e><b data-v-ad8a672e>Trahison</b> : proposer un Pacte, c&#39;est se mettre à nu. Ton « allié » peut ne pas jouer le Pacte et t&#39;attaquer, ou prévenir un autre joueur et partager le butin avec lui par Transfert. </div></div><div class="panel" data-v-ad8a672e><div class="ptitle" data-v-ad8a672e>08 · Transférer</div><ul data-v-ad8a672e><li data-v-ad8a672e>Tu envoies X Batteries à <b data-v-ad8a672e>un seul joueur</b> par tour.</li><li data-v-ad8a672e>Il les reçoit <b data-v-ad8a672e>pendant le tour, avant les attaques</b>, dans sa réserve libre : elles <b class="red" data-v-ad8a672e>peuvent être pillées</b> ce tour-ci.</li></ul></div><div class="panel" data-v-ad8a672e><div class="ptitle" data-v-ad8a672e>09 · Enchère quotidienne</div><ul data-v-ad8a672e><li data-v-ad8a672e><b data-v-ad8a672e>⌊joueurs encore en jeu / 2⌋</b> lots de <b class="teal" data-v-ad8a672e>Razoonium</b> (2 à 8 chacun), visibles par tous et triés du plus gros au plus petit.</li><li data-v-ad8a672e>Les joueurs sont classés par <b data-v-ad8a672e>mise décroissante</b> : le 1ᵉʳ remporte le 1ᵉʳ lot, le 2ᵉ le 2ᵉ lot, etc.</li><li data-v-ad8a672e>Les gagnants <b data-v-ad8a672e>paient leur mise</b> et le Razoonium s&#39;ajoute <b data-v-ad8a672e>directement à leur score</b> (imprenable).</li><li data-v-ad8a672e>Les perdants sont <b data-v-ad8a672e>remboursés</b> dans leur réserve libre, donc pillable ce tour-ci.</li><li data-v-ad8a672e>Égalité de mise : le joueur qui avait le moins de Batteries en début de tour passe devant.</li></ul><div class="ex" data-v-ad8a672e><b data-v-ad8a672e>Exemple</b> : lots du jour 6 et 3. Tristan mise 4, Nat 2, Basto 2 (Nat a moins de Batteries que Basto). Tristan paie 4 et gagne <b class="teal" data-v-ad8a672e>6 Razoonium</b>. Nat paie 2 et gagne <b class="teal" data-v-ad8a672e>3 Razoonium</b>. Basto récupère ses 2 Batteries. </div></div>',6)),e("div",N,[a[16]||(a[16]=e("div",{class:"ptitle"},"10 · Météo (D6)",-1)),a[17]||(a[17]=e("p",{style:{"margin-bottom":"12px"}},"Lancée à chaque résolution : personne ne la connaît au moment de donner ses ordres.",-1)),e("div",h,[e("div",null,[a[7]||(a[7]=e("span",{class:"d"},"1-2",-1)),e("b",w,[s(l,{class:"mi",size:"1.1em",icon:d(p).calm.icon},null,8,["icon"]),a[6]||(a[6]=i(" Calme",-1))]),a[8]||(a[8]=e("span",null,"Aucun effet",-1))]),e("div",null,[a[12]||(a[12]=e("span",{class:"d"},"3-4",-1)),e("b",I,[s(l,{class:"mi",size:"1.1em",icon:d(p).storm.icon},null,8,["icon"]),a[9]||(a[9]=i(" Tempête",-1))]),e("span",null,[a[10]||(a[10]=i("−1 ",-1)),s(l,{class:"mi",size:"1.1em",icon:d(v).battery},null,8,["icon"]),a[11]||(a[11]=i(" supplémentaire pour tous",-1))])]),e("div",null,[a[14]||(a[14]=e("span",{class:"d"},"5-6",-1)),e("b",D,[s(l,{class:"mi",size:"1.1em",icon:d(p).abundance.icon},null,8,["icon"]),a[13]||(a[13]=i(" Abondance",-1))]),a[15]||(a[15]=e("span",null,"Génération ×2 · Pacte ×2,5",-1))])])]),a[21]||(a[21]=n('<div class="panel" data-v-ad8a672e><div class="ptitle" data-v-ad8a672e>11 · Ordre de résolution</div><ol data-v-ad8a672e><li data-v-ad8a672e><b data-v-ad8a672e>Coût de vie</b> : −1 Batterie par dôme.</li><li data-v-ad8a672e><b data-v-ad8a672e>Météo</b> : lancer du dé (−1 de plus en Tempête).</li><li data-v-ad8a672e><b data-v-ad8a672e>Pactes</b> : vérification de la réciprocité ; Boucliers des proposants inactifs pour ce tour.</li><li data-v-ad8a672e><b data-v-ad8a672e>Boucliers</b> : nouveaux Boucliers actifs immédiatement.</li><li data-v-ad8a672e><b data-v-ad8a672e>Enchères</b> : lots de Razoonium attribués, mises perdantes remboursées dans la réserve.</li><li data-v-ad8a672e><b data-v-ad8a672e>Transferts</b> : arrivée dans la réserve du destinataire.</li><li data-v-ad8a672e><b data-v-ad8a672e>Attaques</b> : Boucliers cassés (les plus anciens d&#39;abord), puis pillage de la réserve, puis de la Génération, puis du Raffinage.</li><li data-v-ad8a672e><b data-v-ad8a672e>Expiration</b> des Boucliers posés il y a 3 tours.</li><li data-v-ad8a672e><b data-v-ad8a672e>Raffinage &amp; Génération</b> sur les mises restantes, plus les Batteries d&#39;attaque restituées et le butin.</li><li data-v-ad8a672e><b data-v-ad8a672e>Bilan</b> : tout dôme à 0 Batterie ou moins s&#39;éteint.</li></ol></div>',1)),s(u,{to:d(x).token?"/":"/login",class:"btn primary block"},{default:q(()=>[...a[18]||(a[18]=[i("Entrer dans l'arène ▸",-1)])]),_:1},8,["to"])])])}}},J=T(O,[["__scopeId","data-v-ad8a672e"]]);export{J as default};
